#include <stdio.h>


int main(void)
{
    int count = 0;
    for (int i = 1; i <= 3; i++) {
        for (int j = 0; j < i; j++) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int count = 0;
    for (int i = 1; i < 9; i *= 2) {
        count++;
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int count = 0;
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            count++;
            break;
        }
    }
    printf("%d\n", count);
    return 0;
}
